-- @case 6: [A06] list price 19.95 and tax rate 12.345 flow into the line unchanged
BEGIN;
DELETE FROM sales.orders;
DELETE FROM sales.order_lines;
DELETE FROM warehouse.stock_items;
DELETE FROM sales.customers;
DELETE FROM sales.special_deals;
DELETE FROM warehouse.stock_item_stock_groups;
INSERT INTO warehouse.stock_items ("StockItemID", "UnitPackageID", "TaxRate", "UnitPrice") VALUES
  ('1', '7', '15.000', '19.95'),
  ('2', '9', '12.345', '99.99');
INSERT INTO sales.customers ("CustomerID", "BuyingGroupID", "CustomerCategoryID") VALUES
  ('1', NULL, '1'),
  ('2', '1', '2');
ALTER SEQUENCE sequences."OrderID" RESTART WITH 73596;
CREATE TEMP TABLE pp_outcome (outcome text) ON COMMIT DROP;
DO $pp$
BEGIN
  CALL website.insert_customer_orders(website.order_list_from_json('[{"OrderReference":1,"CustomerID":1,"ContactPersonID":3,"ExpectedDeliveryDate":"2030-01-01","CustomerPurchaseOrderNumber":"PO-1","IsUndersupplyBackordered":false,"Comments":null,"DeliveryInstructions":null},{"OrderReference":2,"CustomerID":2,"ContactPersonID":3,"ExpectedDeliveryDate":"2030-01-01","CustomerPurchaseOrderNumber":"PO-2","IsUndersupplyBackordered":false,"Comments":null,"DeliveryInstructions":null}]'::jsonb), website.order_line_list_from_json('[{"OrderReference":1,"StockItemID":1,"Description":"line 1/1","Quantity":2},{"OrderReference":1,"StockItemID":2,"Description":"line 1/2","Quantity":2},{"OrderReference":2,"StockItemID":1,"Description":"line 2/1","Quantity":2},{"OrderReference":2,"StockItemID":2,"Description":"line 2/2","Quantity":2}]'::jsonb), '1'::integer, '2'::integer);
  INSERT INTO pp_outcome VALUES ('completed');
EXCEPTION
  WHEN SQLSTATE '23502' THEN INSERT INTO pp_outcome VALUES ('raised: NULL into a NOT NULL column');
  WHEN SQLSTATE '22001' THEN INSERT INTO pp_outcome VALUES ('raised: string truncation');
  WHEN SQLSTATE '22003' THEN INSERT INTO pp_outcome VALUES ('raised: numeric overflow');
END $pp$;
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT 'completed'::text AS outcome) EXCEPT ALL (SELECT outcome FROM pp_outcome)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT outcome FROM pp_outcome) EXCEPT ALL (SELECT 'completed'::text AS outcome)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the outcome', 'test 06 [A06 list price 19.95 and tax rate 12.345 flow into the line unchanged', missing, extra;
  END IF;
END $pp$;
